import{_ as a,o as t,c as r,a2 as n}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"Epic: Search Connector","description":"","frontmatter":{},"headers":[],"relativePath":"sovereign-edge/epics/search-connector.md","filePath":"sovereign-edge/epics/search-connector.md"}'),o={name:"sovereign-edge/epics/search-connector.md"};function s(i,e,c,l,h,d){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="epic-search-connector" tabindex="-1">Epic: Search Connector <a class="header-anchor" href="#epic-search-connector" aria-label="Permalink to &quot;Epic: Search Connector&quot;">​</a></h1><blockquote><p>The default, built-in Tier 1 connector for scenario 2 — web search — the one connector that ships in the Phase 1 MVP.</p></blockquote><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>📋 Planned</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The first real consumer of the <a href="./connector-framework.html">Connector Framework</a>. Ships hardcoded/bundled in Phase 1, but expressed in the exact Tier 1 manifest shape a downloadable third-party connector will use later — no special-casing.</p><p>Defaults toward a configurable meta-search endpoint (SearXNG-style) rather than one company&#39;s API, aligned with <code>sovereign-os</code>&#39;s independent ADR-0004 decision (see research 0001).</p><h2 id="tasks" tabindex="-1">Tasks <a class="header-anchor" href="#tasks" aria-label="Permalink to &quot;Tasks&quot;">​</a></h2><h4 id="📋-3-1-—-default-search-connector" tabindex="-1">📋 3.1 — Default Search connector <a class="header-anchor" href="#📋-3-1-—-default-search-connector" aria-label="Permalink to &quot;📋 3.1 — Default Search connector&quot;">​</a></h4><p><strong>Goal:</strong> A working Tier 1 connector that lets the model answer questions needing current web information.</p><p><strong>Deliverables:</strong></p><ul><li>Search connector manifest (per epic 2&#39;s schema): tool schema for <code>web.search</code>, request/response templates for a meta-search HTTP API.</li><li>Permission-gated per the Connector Framework — disabled until the user explicitly grants network access to this specific connector.</li><li>Result summarization back into the chat, with provenance shown (epic 2.5).</li></ul><p><strong>Dependencies:</strong> Connector Framework epic (2.1–2.4).</p><p><strong>Review checklist:</strong></p><ul><li>With the connector permission denied, a search-requiring question is answered by explaining the connector isn&#39;t enabled, not by silently failing or hallucinating an answer.</li><li>With permission granted, a real search round-trips and the reply cites that the Search connector was used.</li></ul><hr><h4 id="📋-3-2-—-configurable-meta-search-endpoint" tabindex="-1">📋 3.2 — Configurable meta-search endpoint <a class="header-anchor" href="#📋-3-2-—-configurable-meta-search-endpoint" aria-label="Permalink to &quot;📋 3.2 — Configurable meta-search endpoint&quot;">​</a></h4><p><strong>Goal:</strong> Avoid hardcoding a single company&#39;s search API — let the endpoint be user-configurable, consistent with the wider ecosystem&#39;s self-hosting bent.</p><p><strong>Deliverables:</strong></p><ul><li>Settings field for a custom SearXNG (or compatible) instance URL.</li><li>A sane default endpoint for users who don&#39;t want to self-host one (exact choice still an open question — see research 0001).</li></ul><p><strong>Dependencies:</strong> Task 3.1.</p><p><strong>Review checklist:</strong></p><ul><li>Pointing the connector at a different, user-supplied SearXNG-compatible endpoint works without a code change.</li></ul><h2 id="related-docs" tabindex="-1">Related Docs <a class="header-anchor" href="#related-docs" aria-label="Permalink to &quot;Related Docs&quot;">​</a></h2><ul><li><a href="./../../CONCEPT.html">CONCEPT.md</a></li><li><a href="./../research/0001-concept-and-connector-architecture.html">research 0001</a></li><li><a href="./connector-framework.html">Connector Framework</a></li></ul>',25)])])}const m=a(o,[["render",s]]);export{u as __pageData,m as default};
